import {createEnemy,animateEnemy} from './enemy-art.js';
import {run,THREE,box,sphere,floor,ring,makeHero,poseHero} from './lib/core.js';import {Arena} from './rules.js';
run({title:'Rift Arena',genre:'Anime / wave survival',accent:'#c4a6ff',description:'Five waves. One tiny arena. Dodge, fire, collect energy and unleash a room-clearing burst against a growing mix of enemies.',controls:[['W A S D','Move'],['J / hold click','Fire'],['Space','Dodge'],['K','Pulse'],['E','Ultimate at 100 energy'],['Mouse','Aim in cursor mode']],touch:[['KeyA','←'],['KeyD','→'],['KeyW','↑'],['KeyS','↓'],['KeyJ','Fire'],['Space','Dodge'],['KeyK','Pulse'],['KeyE','Burst']],options:[{id:'aim',label:'Aim style',values:[['auto','Auto-target · keyboard / touch'],['cursor','Mouse cursor aim']]}],buildIntro:'An original top-down anime arena game built around readable attacks, cooldowns and a short five-wave challenge.',build:[['Arena hero in Blender','Modelled a Vegeta fan model with a chest core, spiked hair and distinct material groups, exported as a GLB.'],['Combat simulation','Separated movement, projectile lifetimes, hit tests, cooldowns, damage invulnerability and energy gains into a testable rule module.'],['Enemy behaviours','Five original enemy designs: articulated Rift Stalkers, floating Hex Oracles, armoured Iron Bastions, telegraphed Ember Ravagers and orbiting Prism Wardens with spread shots. Damaged enemies show health bars.'],['Progression and feedback','Five waves, healing drops, dodge timing, a pulse attack and a charge-gated ultimate create a complete win/loss loop.']]},(ctx,model)=>{const {scene,camera,stage}=ctx;floor(scene,140,0x10182c);box(scene,0,-.2,0,31,.4,31,0x282f4c);for(const x of [-15.5,15.5]){box(scene,x,.5,0,.3,1,31,0x55577c);box(scene,x,1.02,0,.13,.05,31,0xb393f5)}for(const z of [-15.5,15.5]){box(scene,0,.5,z,31,1,.3,0x55577c);box(scene,0,1.02,z,31,.05,.13,0xb393f5)}for(let x=-12;x<=12;x+=4)for(let z=-12;z<=12;z+=4)ring(scene,x,.02,z,.16,0x57527c);const hero=makeHero(model,scene,.62),aura=ring(scene,0,.04,0,1.2,0xc7a1ff),pulse=ring(scene,0,.1,0,1,0xc7a1ff),enemies=new Map(),bullets=new Map(),pickups=new Map(),pointer=new THREE.Vector2(),ray=new THREE.Raycaster(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hit=new THREE.Vector3();let sim=new Arena(),aim={x:0,z:-1},pulseLife=0,finished=false;camera.position.set(0,26,21);camera.lookAt(0,0,0);
stage.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height)*2+1);ray.setFromCamera(pointer,camera);if(ray.ray.intersectPlane(plane,hit))aim={x:hit.x-sim.player.x,z:hit.z-sim.player.z}});stage.addEventListener('pointerdown',e=>{if(ctx.playing&&e.button===0)ctx.keys.add('KeyJ')});window.addEventListener('pointerup',e=>{if(stage.contains(e.target))ctx.keys.delete('KeyJ')});
function sync(map,items,create,place){const ids=new Set(items.map(i=>i.id));for(const [id,m]of map)if(!ids.has(id)){scene.remove(m);m.traverse(o=>{if(o.isMesh){o.geometry?.dispose();o.material?.dispose()}});map.delete(id)}for(const item of items){if(!map.has(item.id))map.set(item.id,create(item));place(map.get(item.id),item)}}
return {reset(o){sim=new Arena(o);finished=false;pulseLife=0;ctx.announce('Hold J to fire · dodge with Space')},update(dt){sim.update(dt,ctx.keys,ctx.pressed,aim);const p=sim.player;hero.position.set(p.x,0,p.z);hero.rotation.y=Math.atan2(p.aimX,p.aimZ);hero.scale.setScalar(p.dash>0?.9:1);aura.position.set(p.x,.04,p.z);aura.visible=p.inv>0;aura.rotation.z+=dt;hero.userData.character.position.y=hero.userData.baseY+Math.sin(ctx.time*8)*.015;poseHero(hero,ctx.time,ctx.keys.has('KeyW')||ctx.keys.has('KeyA')||ctx.keys.has('KeyS')||ctx.keys.has('KeyD')?1:0);
sync(enemies,sim.enemies,e=>createEnemy(e,scene),(m,e)=>animateEnemy(m,e,p,ctx.time,dt,camera));sync(bullets,sim.bullets,b=>sphere(scene,0,.8,0,b.enemy?.18:.13,b.enemy?0xffa28e:0xc4a8ff),(m,b)=>m.position.set(b.x,.85,b.z));sync(pickups,sim.pickups,()=>sphere(scene,0,.5,0,.28,0x8df1bc),(m,h)=>{m.position.set(h.x,.5+Math.sin(ctx.time*3)*.1,h.z)});
for(const e of sim.events){if(e==='wave')ctx.announce('Wave '+sim.wave+' / 5');if(e==='pulse'||e==='ultimate'){pulseLife=.5;pulse.position.set(p.x,.1,p.z);pulse.userData.ultimate=e==='ultimate';ctx.tone(220,.25)}if(e==='kill')ctx.tone(540,.05);if(e==='heal')ctx.announce('Health restored.')}pulseLife=Math.max(0,pulseLife-dt);pulse.visible=pulseLife>0;pulse.scale.setScalar((1-pulseLife/.5)*(pulse.userData.ultimate?20:4));ctx.hud(`<div><strong>WAVE ${Math.max(1,sim.wave)} / 5</strong><small>${sim.kills} DEFEATED · ${sim.enemies.length} REMAIN · ${Math.round(sim.time)}s</small><div class="meter"><i style="width:${p.hp}%"></i></div><small>HEALTH ${Math.ceil(p.hp)}</small></div><div><strong>${p.energy} ENERGY</strong><small>${p.energy>=100?'ULTIMATE READY · E':'BUILD ENERGY WITH KILLS'}</small><small>DODGE ${p.dashCd>0?p.dashCd.toFixed(1)+'s':'READY'} · PULSE ${p.pulseCd>0?p.pulseCd.toFixed(1)+'s':'READY'}</small></div>`);if(sim.over&&!finished){finished=true;ctx.end(sim.won?'The rift is closed.':'The arena calls you back.',`${sim.kills} enemies defeated in ${Math.round(sim.time)} seconds. ${sim.won?'All five waves complete.':'Collect healing drops and save your dodge for incoming shots.'}`)}},snapshot(){return {wave:sim.wave,hp:sim.player.hp,kills:sim.kills,enemies:sim.enemies.length,enemyTypes:[...new Set(sim.enemies.map(e=>e.type))],over:sim.over,won:sim.won}}};});
